import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.Dkj3JE0_.js";const p=JSON.parse('{"title":"JLPT N2 Plan","description":"","frontmatter":{"title":"JLPT N2 Plan"},"headers":[],"relativePath":"blogs/JLPT-N2/plan.md","filePath":"blogs/JLPT-N2/plan.md"}'),r={name:"blogs/JLPT-N2/plan.md"};function s(l,e,o,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="jlpt-n2-learning-plan" tabindex="-1">JLPT N2 Learning Plan <a class="header-anchor" href="#jlpt-n2-learning-plan" aria-label="Permalink to &quot;JLPT N2 Learning Plan&quot;">​</a></h1><blockquote><p><strong>Working assumption:</strong> a 24-week runway and about <strong>7 hours per week</strong>. The plan targets both the exam and useful Japanese, so reading and listening stay connected to real material.</p></blockquote><h2 id="definition-of-done" tabindex="-1">Definition of done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of done&quot;">​</a></h2><ul><li>Recognize the core N2 vocabulary and kanji in context, not only on flashcards.</li><li>Read an N2-length passage with a clear purpose, structure map, and controlled pace.</li><li>Follow the main claim, stance, and important details in one-pass listening.</li><li>Pass three timed practice tests with a margin above the required sectional and total scores.</li></ul><h2 id="weekly-rhythm" tabindex="-1">Weekly rhythm <a class="header-anchor" href="#weekly-rhythm" aria-label="Permalink to &quot;Weekly rhythm&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Frequency</th><th style="text-align:right;">Time</th><th>Work</th></tr></thead><tbody><tr><td>Daily</td><td style="text-align:right;">20 min</td><td>Spaced review: vocabulary, kanji, and one example sentence aloud.</td></tr><tr><td>3× weekly</td><td style="text-align:right;">35 min</td><td>Grammar pattern → contrast with a similar pattern → 8–12 questions.</td></tr><tr><td>3× weekly</td><td style="text-align:right;">30 min</td><td>Active listening: predict, listen once, summarize, then check transcript.</td></tr><tr><td>2× weekly</td><td style="text-align:right;">45 min</td><td>Timed reading followed by structure and error analysis.</td></tr><tr><td>Weekend</td><td style="text-align:right;">90 min</td><td>Mixed section practice plus weekly review.</td></tr></tbody></table><h2 id="_24-week-roadmap" tabindex="-1">24-week roadmap <a class="header-anchor" href="#_24-week-roadmap" aria-label="Permalink to &quot;24-week roadmap&quot;">​</a></h2><h3 id="phase-1-—-baseline-and-system-weeks-1–2" tabindex="-1">Phase 1 — Baseline and system (Weeks 1–2) <a class="header-anchor" href="#phase-1-—-baseline-and-system-weeks-1–2" aria-label="Permalink to &quot;Phase 1 — Baseline and system (Weeks 1–2)&quot;">​</a></h3><ul><li>Take a timed sample covering language knowledge, reading, and listening.</li><li>Classify mistakes: vocabulary, grammar nuance, sentence connection, reading speed, missed cue, or attention.</li><li>Choose one main course or book for each skill. Extra resources go on a waiting list.</li><li>Start a sentence-based review deck; cap new items so reviews stay below 25 minutes.</li></ul><h3 id="phase-2-—-coverage-weeks-3–12" tabindex="-1">Phase 2 — Coverage (Weeks 3–12) <a class="header-anchor" href="#phase-2-—-coverage-weeks-3–12" aria-label="Permalink to &quot;Phase 2 — Coverage (Weeks 3–12)&quot;">​</a></h3><ul><li>Learn 12–15 vocabulary items and 4–6 kanji per day, six days per week.</li><li>Learn 8–10 grammar patterns per week in contrast groups such as cause, concession, limitation, and tendency.</li><li>Read one short authentic text daily: NHK, an essay, a product page, or a workplace notice.</li><li>Listen to 15–20 minutes of Japanese daily. On three days, do an intensive replay with a transcript.</li></ul><p>Every Sunday, write a 150–250 character summary using two of the week’s grammar patterns.</p><h3 id="phase-3-—-speed-and-integration-weeks-13–18" tabindex="-1">Phase 3 — Speed and integration (Weeks 13–18) <a class="header-anchor" href="#phase-3-—-speed-and-integration-weeks-13–18" aria-label="Permalink to &quot;Phase 3 — Speed and integration (Weeks 13–18)&quot;">​</a></h3><ul><li>Shift from isolated questions to timed reading and listening sets.</li><li>For reading, mark the author’s claim, contrast words, referents, and paragraph job.</li><li>For listening, predict the question type and capture only decision-changing details.</li><li>Shadow one 60–90 second clip three times per week for sound recognition and rhythm.</li><li>Maintain old vocabulary; reduce new cards if recall drops below 85%.</li></ul><h3 id="phase-4-—-test-readiness-weeks-19–23" tabindex="-1">Phase 4 — Test readiness (Weeks 19–23) <a class="header-anchor" href="#phase-4-—-test-readiness-weeks-19–23" aria-label="Permalink to &quot;Phase 4 — Test readiness (Weeks 19–23)&quot;">​</a></h3><ul><li>Alternate full section tests and full practice exams each weekend.</li><li>Recreate actual timing, breaks, audio playback, and answer-sheet behavior.</li><li>Review why each distractor is wrong, especially when the correct answer was guessed.</li><li>Use weekday sessions to repair one weak subskill at a time.</li></ul><h3 id="phase-5-—-taper-week-24" tabindex="-1">Phase 5 — Taper (Week 24) <a class="header-anchor" href="#phase-5-—-taper-week-24" aria-label="Permalink to &quot;Phase 5 — Taper (Week 24)&quot;">​</a></h3><ul><li>Review high-confusion grammar pairs, recurring kanji readings, and listening cue words.</li><li>Do brief timed sets without exhausting full tests.</li><li>Confirm logistics and protect sleep.</li></ul><h2 id="monthly-real-world-checkpoint" tabindex="-1">Monthly real-world checkpoint <a class="header-anchor" href="#monthly-real-world-checkpoint" aria-label="Permalink to &quot;Monthly real-world checkpoint&quot;">​</a></h2><p>Once every four weeks:</p><ul><li>read one article and give a two-minute spoken summary;</li><li>hold a 20-minute conversation or language exchange;</li><li>write one short professional message and have it corrected;</li><li>note what the test study is—and is not—improving.</li></ul><h2 id="first-seven-days" tabindex="-1">First seven days <a class="header-anchor" href="#first-seven-days" aria-label="Permalink to &quot;First seven days&quot;">​</a></h2><ul><li>[ ] Take the baseline sample and record sectional scores.</li><li>[ ] Select one core resource per skill.</li><li>[ ] Create the review deck and error log.</li><li>[ ] Save three reliable reading and listening sources.</li><li>[ ] Schedule the first 90-minute mixed practice block.</li></ul>',23)])])}const m=a(r,[["render",s]]);export{p as __pageData,m as default};
